cd /home/agus/workspace/asermax/nagara/.scratch/cloudflare-migration/spikes/r2-presigned/worker; mkdir -p src
cat > src/common.ts <<'EOF'
export interface Env {
  R2_ACCESS_KEY_ID: string
  R2_SECRET_ACCESS_KEY: string
  ACCOUNT_ID: string
  BUCKET: string
  API_KEY: string
}
export const CT = (key: string) => (key.endsWith(".ogg") ? "audio/ogg" : "application/octet-stream")
EOF
cat > src/aws4.ts <<'EOF'
import { AwsClient } from "aws4fetch"
import type { Env } from "./common"
import { CT } from "./common"

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url)
    const m = url.pathname.match(/^\/items\/([^/]+)\/audio$/)
    if (!m) return new Response("not found", { status: 404 })
    if (req.headers.get("x-api-key") !== env.API_KEY && url.searchParams.get("key") !== env.API_KEY) return new Response("unauthorized", { status: 401 })
    const ttl = Number(url.searchParams.get("ttl") ?? 3600)
    const key = `${m[1]}.ogg`
    const client = new AwsClient({ accessKeyId: env.R2_ACCESS_KEY_ID, secretAccessKey: env.R2_SECRET_ACCESS_KEY, service: "s3", region: "auto" })
    const target = new URL(`https://${env.BUCKET}.${env.ACCOUNT_ID}.r2.cloudflarestorage.com/${key}`)
    target.searchParams.set("X-Amz-Expires", String(ttl))
    target.searchParams.set("response-content-type", CT(key))
    const signed = await client.sign(new Request(target, { method: "GET" }), { aws: { signQuery: true } })
    return new Response(null, { status: 307, headers: { location: signed.url } })
  },
}
EOF
cat > src/sdk.ts <<'EOF'
import { S3Client, GetObjectCommand } from "@aws-sdk/client-s3"
import { getSignedUrl } from "@aws-sdk/s3-request-presigner"
import type { Env } from "./common"
import { CT } from "./common"

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url)
    const m = url.pathname.match(/^\/items\/([^/]+)\/audio$/)
    if (!m) return new Response("not found", { status: 404 })
    if (req.headers.get("x-api-key") !== env.API_KEY && url.searchParams.get("key") !== env.API_KEY) return new Response("unauthorized", { status: 401 })
    const ttl = Number(url.searchParams.get("ttl") ?? 3600)
    const key = `${m[1]}.ogg`
    const s3 = new S3Client({
      region: "auto",
      endpoint: `https://${env.ACCOUNT_ID}.r2.cloudflarestorage.com`,
      credentials: { accessKeyId: env.R2_ACCESS_KEY_ID, secretAccessKey: env.R2_SECRET_ACCESS_KEY },
    })
    const signed = await getSignedUrl(s3, new GetObjectCommand({ Bucket: env.BUCKET, Key: key, ResponseContentType: CT(key) }), { expiresIn: ttl })
    return new Response(null, { status: 307, headers: { location: signed } })
  },
}
EOF
for v in aws4 sdk; do
cat > wrangler.$v.jsonc <<EOF
{ "name": "nagara-spike-r2-presigned$([ $v = sdk ] && echo -sdk)", "main": "src/$v.ts", "compatibility_date": "2026-09-01", "compatibility_flags": ["nodejs_compat"],
  "vars": { "ACCOUNT_ID": "2b32439a1d8fdcdf00a9f7f654a11a6d", "BUCKET": "nagara-spike-r2-presigned" } }
EOF
npx wrangler deploy -c wrangler.$v.jsonc --dry-run --outdir dist-$v 2>&1 | grep -E "Total Upload|ERROR|error"
done

